// Scheduled email update brief (research.briefBinding of the scheduled_draft feature). Read-only: records.read on Investor Updates'
// own roles and the shared people and organizations. The run is for one plan (input.recordId): its template (sections, default
// levels, brief, design), its categories with their descriptions, levels and share-class rules, the share classes (information
// rights in words), the plan's sources and exclusions, the period to draft (the app's period rules), the previous sent update of
// the plan with its blocks, facts and dated statements, and that update's engagement (who did not read, open asks, unanswered
// questions). It marks when the period already has an update, so research saves nothing (dedup by plan + period).
const MAX_PAGES=8;
function readAll(role){const typeId=appRoles[role];if(!typeId)return {rows:[],complete:false};let rows=[],total=0;
 for(let page=0;page<MAX_PAGES;page++){const r=tools.call('records.read',{typeId,limit:100,offset:page*100});const got=r&&Array.isArray(r.rows)?r.rows:[];
  rows=rows.concat(got);total=Number(r&&r.total)||rows.length;if(!got.length||rows.length>=total)break;}
 return {rows:rows.map(x=>Object.assign({},x.data||{},{id:x.id})),complete:rows.length>=total};}
const live=r=>r.archived!==true&&r.archived!=='true';
const J=v=>{try{const x=typeof v==='string'?JSON.parse(v):v;return x&&typeof x==='object'?x:null;}catch(e){return null;}};
const L=v=>{const x=J(v);return Array.isArray(x)?x.map(String):[];};
const today=new Date().toISOString().slice(0,10);
const monthEnd=(y,m)=>new Date(Date.UTC(y,m,0)).toISOString().slice(0,10);
const addDays=(d,n)=>new Date(Date.parse(d+'T00:00:00Z')+n*86400000).toISOString().slice(0,10);
function periodOf(cad,d){const y=Number(d.slice(0,4)),m=Number(d.slice(5,7));
 if(cad==='quarterly'){const q=Math.ceil(m/3);return {key:y+'-Q'+q,start:y+'-'+String(q*3-2).padStart(2,'0')+'-01',end:monthEnd(y,q*3)};}
 if(cad==='half_yearly'){const h=m<=6?1:2;return {key:y+'-H'+h,start:y+'-'+(h===1?'01':'07')+'-01',end:monthEnd(y,h*6)};}
 if(cad==='yearly')return {key:String(y),start:y+'-01-01',end:y+'-12-31'};
 return {key:y+'-'+String(m).padStart(2,'0'),start:y+'-'+String(m).padStart(2,'0')+'-01',end:monthEnd(y,m)};}
const R={};for(const role of ['investorupdates.plans','investorupdates.templates','investorupdates.categories','investorupdates.share_classes','investorupdates.updates','investorupdates.deliveries','investorupdates.responses','investorupdates.recipients','investorupdates.settings','people','organizations'])R[role]=readAll(role);
const byId=role=>Object.fromEntries(R[role].rows.map(r=>[r.id,r]));
const PLAN=byId('investorupdates.plans'),TPL=byId('investorupdates.templates'),CAT=byId('investorupdates.categories'),CLS=byId('investorupdates.share_classes'),REC=byId('investorupdates.recipients'),PEOPLE=byId('people'),ORG=byId('organizations');
const plan=PLAN[input&&input.recordId];
if(!plan||!live(plan))return {context:JSON.stringify({skip:true,reason:'The plan is not available or archived: save nothing.'})};
const settings=R['investorupdates.settings'].rows[0]||{};
const cadence=plan.cadence||'monthly';
// The period to draft: the last period that has ended (the app shows it as due until an update for it is sent).
const due=periodOf(cadence,addDays(periodOf(cadence,today).start,-1));
const ups=R['investorupdates.updates'].rows.filter(u=>u.plan_id===plan.id);
const existing=ups.find(u=>u.period===due.key&&u.status!=='cancelled');
const prev=ups.filter(u=>u.status==='sent').sort((a,b)=>String(b.sent_on||'').localeCompare(String(a.sent_on||'')))[0]||null;
const tpl=TPL[plan.template_id]||null;
const cats=L(plan.category_ids).map(id=>CAT[id]).filter(c=>c&&live(c));
const classIds=[...new Set(cats.flatMap(c=>L(c.share_class_ids)))];
let engagement=null;
if(prev){const ds=R['investorupdates.deliveries'].rows.filter(d=>d.update_id===prev.id),delivered=ds.filter(d=>['sent','read'].includes(d.status)||Number(d.read_count)>0),read=delivered.filter(d=>d.status==='read'||Number(d.read_count)>0);
 const rs=R['investorupdates.responses'].rows.filter(r=>ups.some(u=>u.id===r.update_id));
 const nameOf=id=>{const r=REC[id];return r&&PEOPLE[r.person_id]?PEOPLE[r.person_id].name:null;};
 engagement={update:prev.title,sent_on:prev.sent_on||null,delivered:delivered.length,read:read.length,not_read:delivered.filter(d=>!(d.status==='read'||Number(d.read_count)>0)).map(d=>nameOf(d.recipient_id)).filter(Boolean).slice(0,30),
  open_asks:rs.filter(r=>r.ask_key!=='question'&&r.kind!=='question'&&['new','following_up',undefined,null,''].includes(r.status)).map(r=>({ask:r.ask_text||r.ask_key,note:r.message||null})).slice(0,20),
  unanswered_questions:rs.filter(r=>(r.ask_key==='question'||r.kind==='question')&&!r.answered_on).map(r=>String(r.message||'').slice(0,300)).slice(0,20)};}
const dated=prev?(J(prev.blocks)||[]).filter(b=>b&&b.type==='milestones').flatMap(b=>(b.items||[]).map(m=>({title:m.title,date:m.date,status:m.status}))).slice(0,30):[];
const context={
 asOf:today,
 instruction:existing?'This period already has an update ('+existing.status+'): save nothing and complete with no update.':'Create one investorupdates.updates row for this period, status in_review.',
 plan:{id:plan.id,name:plan.name,format:plan.format,cadence,period:due.key,period_start:due.start,period_end:due.end,send_by_day:plan.send_by_day??7,approvers:[plan.approver_1||null,plan.approver_2||null],sources:J(plan.sources)||{},status:plan.status},
 existing_update:existing?{id:existing.id,status:existing.status}:null,
 template:tpl?{id:tpl.id,name:tpl.name,format:tpl.format,sections:J(tpl.sections)||[],brief:tpl.brief||null,design:J(tpl.design)||{}}:null,
 categories:cats.map(c=>({id:c.id,name:c.name,kind:c.kind,level:c.level,description:c.description||null,share_class_rule:L(c.share_class_ids).map(id=>CLS[id]?CLS[id].name:null).filter(Boolean),help_on:c.help_on!==false,questions_on:c.questions_on!==false})),
 share_classes:classIds.map(id=>CLS[id]).filter(Boolean).map(c=>({name:c.name,kind:c.kind,notes:c.notes||null})),
 settings:{help_enabled:settings.help_enabled!==false,questions_enabled:settings.questions_enabled!==false},
 previous_update:prev?{id:prev.id,title:prev.title,period:prev.period,sent_on:prev.sent_on||null,blocks:J(prev.blocks)||[],facts:J(prev.facts)||[],dated_statements:dated}:null,
 engagement,
 rules:['Write blocks only (types heading, text, metrics, table, chart, milestones, asks, callout, divider, image), each with a level: board, investors or everyone; follow the template sections and their default levels; never raise a level the user lowered.','Every number in metrics, charts and numeric tables references a fact {id, claim, value, unit, source, as_of}; record sources name app, role, record_id and field; never invent figures; say "not available" when a source is missing.','Lead with cash, runway to the next milestone and program progress; give honest lowlights; make asks specific.','Compare dated statements with previous_update.dated_statements and explain moved dates in the milestone explanation.','Never state ownership percentages or holdings; never mention plan.sources.exclusions; no legal or securities advice.'],
 complete:Object.values(R).every(x=>x.complete)
};
let text=JSON.stringify(context);
while(text.length>60000&&context.previous_update&&context.previous_update.blocks.length){context.previous_update.blocks=context.previous_update.blocks.slice(0,Math.floor(context.previous_update.blocks.length*0.7));context.truncated=true;text=JSON.stringify(context);}
return {context:text};

// Agenda and pre-read brief (research.briefBinding of meeting_before_draft, which fires lead days before a meeting date).
// Read-only. The run is for one meeting (input.recordId). Recipes cannot filter by status, so this brief marks meetings that are
// cancelled, held, already past or that already have a before part: research then saves nothing. Otherwise it gives the meeting,
// its invited categories with descriptions and levels, its plan's template (or the standard agenda template), the plan sources,
// the previous meeting of the same kind with its recap, next steps and questions, and the attached documents to cite.
const MAX_PAGES=8;
function readAll(role){const typeId=appRoles[role];if(!typeId)return {rows:[],complete:false};let rows=[],total=0;
 for(let page=0;page<MAX_PAGES;page++){const r=tools.call('records.read',{typeId,limit:100,offset:page*100});const got=r&&Array.isArray(r.rows)?r.rows:[];
  rows=rows.concat(got);total=Number(r&&r.total)||rows.length;if(!got.length||rows.length>=total)break;}
 return {rows:rows.map(x=>Object.assign({},x.data||{},{id:x.id})),complete:rows.length>=total};}
const live=r=>r.archived!==true&&r.archived!=='true';
const J=v=>{try{const x=typeof v==='string'?JSON.parse(v):v;return x&&typeof x==='object'?x:null;}catch(e){return null;}};
const L=v=>{const x=J(v);return Array.isArray(x)?x.map(String):[];};
const today=new Date().toISOString().slice(0,10);
const R={};for(const role of ['investorupdates.meetings','investorupdates.plans','investorupdates.templates','investorupdates.categories','investorupdates.updates','investorupdates.responses','investorupdates.settings'])R[role]=readAll(role);
const byId=role=>Object.fromEntries(R[role].rows.map(r=>[r.id,r]));
const MEET=byId('investorupdates.meetings'),PLAN=byId('investorupdates.plans'),TPL=byId('investorupdates.templates'),CAT=byId('investorupdates.categories');
const m=MEET[input&&input.recordId];
const ups=R['investorupdates.updates'].rows;
const before=m?ups.find(u=>u.meeting_id===m.id&&u.format==='meeting_before'&&u.status!=='cancelled'):null;
const skip=!m||!live(m)?'The meeting is not available or archived.':m.status==='cancelled'?'The meeting is cancelled.':m.status==='held'?'The meeting was already held.':String(m.meeting_date||'')<today?'The meeting date has passed.':before?'The meeting already has its before part ('+before.status+').':null;
if(skip)return {context:JSON.stringify({skip:true,reason:skip+' Save nothing and complete with no update.'})};
const plan=m.plan_id?PLAN[m.plan_id]:null;
const tpl=plan&&TPL[plan.template_id]||R['investorupdates.templates'].rows.find(t=>t.kind==='meeting_before'&&live(t))||null;
const prevMeeting=R['investorupdates.meetings'].rows.filter(x=>x.id!==m.id&&x.kind===m.kind&&live(x)&&String(x.meeting_date||'')<String(m.meeting_date)).sort((a,b)=>String(b.meeting_date).localeCompare(String(a.meeting_date)))[0]||null;
const prevParts=prevMeeting?ups.filter(u=>u.meeting_id===prevMeeting.id&&u.status==='sent'):[];
const qs=prevParts.length?R['investorupdates.responses'].rows.filter(r=>prevParts.some(u=>u.id===r.update_id)&&(r.ask_key==='question'||r.kind==='question')).map(r=>({question:String(r.message||'').slice(0,300),answered:!!r.answered_on})):[];
const settings=R['investorupdates.settings'].rows[0]||{};
const context={
 asOf:today,
 instruction:'Create one investorupdates.updates row: format meeting_before, meeting_id '+m.id+', kind one_off, status in_review, category_ids = the invited categories, document_ids = the platform documents you cite.',
 meeting:{id:m.id,title:m.title,kind:m.kind,date:m.meeting_date,start_time:m.start_time||null,timezone:m.timezone||null,location:m.location||null,plan:plan?{id:plan.id,name:plan.name,sources:J(plan.sources)||{}}:null},
 invited:L(m.category_ids).map(id=>CAT[id]).filter(Boolean).map(c=>({id:c.id,name:c.name,level:c.level,description:c.description||null,questions_on:c.questions_on!==false})),
 template:tpl?{id:tpl.id,name:tpl.name,sections:J(tpl.sections)||[],brief:tpl.brief||null}:null,
 previous_meeting:prevMeeting?{title:prevMeeting.title,date:prevMeeting.meeting_date,parts:prevParts.map(u=>({format:u.format,title:u.title,blocks:J(u.blocks)||[]})),questions:qs}:null,
 settings:{questions_enabled:settings.questions_enabled!==false,lead_days:settings.meeting_lead_days??7},
 rules:['Blocks: meeting (date, time, place as text), agenda (title, presenter, minutes, document_id of an attached platform document), text for the pre-read, each with a level: board, investors or everyone; decisions needed are board level.','Agenda from open decisions, milestones and the previous meeting\'s next steps; cite only platform documents you attach.','Every number references a fact with its source; never invent figures.','No legal advice; the meeting procedure (notices, votes, quorum) is out of scope.'],
 complete:Object.values(R).every(x=>x.complete)
};
let text=JSON.stringify(context);
while(text.length>60000&&context.previous_meeting&&context.previous_meeting.parts.length){context.previous_meeting.parts=context.previous_meeting.parts.slice(0,-1);context.truncated=true;text=JSON.stringify(context);}
return {context:text};

// Weekly Investor Updates digest (email.summaryBinding of weekly_digest, Mondays 08:00). Read-only: records.read on the app's own
// roles. Same rules as the app: an email plan's last ended period is due until its update is sent, send-by = period end +
// send_by_day, overdue after that; a meeting's before part is due meeting_lead_days ahead. Sections: email updates due or
// overdue, meetings in the next 21 days with their before status, meetings held without an after part, drafts waiting for
// approval, unanswered questions, open offers of help. Nothing to report sends nothing (nonEmpty:false). Partial reads say so.
const MAX_PAGES=8;
function readAll(role){const typeId=appRoles[role];if(!typeId)return {rows:[],complete:false};let rows=[],total=0;
 for(let page=0;page<MAX_PAGES;page++){const r=tools.call('records.read',{typeId,limit:100,offset:page*100});const got=r&&Array.isArray(r.rows)?r.rows:[];
  rows=rows.concat(got);total=Number(r&&r.total)||rows.length;if(!got.length||rows.length>=total)break;}
 return {rows:rows.map(x=>Object.assign({},x.data||{},{id:x.id})),complete:rows.length>=total};}
const live=r=>r.archived!==true&&r.archived!=='true';
const today=new Date().toISOString().slice(0,10);
const monthEnd=(y,m)=>new Date(Date.UTC(y,m,0)).toISOString().slice(0,10);
const addDays=(d,n)=>new Date(Date.parse(d+'T00:00:00Z')+n*86400000).toISOString().slice(0,10);
const MON=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
const day=d=>Number(d.slice(8,10))+' '+MON[Number(d.slice(5,7))-1];
function periodOf(cad,d){const y=Number(d.slice(0,4)),m=Number(d.slice(5,7));
 if(cad==='quarterly'){const q=Math.ceil(m/3);return {key:y+'-Q'+q,label:'Q'+q+' '+y,start:y+'-'+String(q*3-2).padStart(2,'0')+'-01',end:monthEnd(y,q*3)};}
 if(cad==='half_yearly'){const h=m<=6?1:2;return {key:y+'-H'+h,label:'H'+h+' '+y,start:y+'-'+(h===1?'01':'07')+'-01',end:monthEnd(y,h*6)};}
 if(cad==='yearly')return {key:String(y),label:String(y),start:y+'-01-01',end:y+'-12-31'};
 return {key:y+'-'+String(m).padStart(2,'0'),label:MON[m-1]+' '+y,start:y+'-'+String(m).padStart(2,'0')+'-01',end:monthEnd(y,m)};}
const R={};for(const role of ['investorupdates.plans','investorupdates.meetings','investorupdates.updates','investorupdates.responses','investorupdates.settings'])R[role]=readAll(role);
const settings=R['investorupdates.settings'].rows[0]||{},lead=Number.isFinite(Number(settings.meeting_lead_days))&&settings.meeting_lead_days!==null&&settings.meeting_lead_days!==''?Number(settings.meeting_lead_days):7;
const ups=R['investorupdates.updates'].rows,sec=[],more=(xs,n)=>xs.length>n?' · '+(xs.length-n)+' more':'';
const due=[];for(const p of R['investorupdates.plans'].rows.filter(p=>live(p)&&p.status==='active'&&p.format==='email')){const d=periodOf(p.cadence||'monthly',addDays(periodOf(p.cadence||'monthly',today).start,-1));
 const u=ups.filter(x=>x.plan_id===p.id&&x.period===d.key&&x.status!=='cancelled');if(u.some(x=>x.status==='sent'))continue;const sendBy=addDays(d.end,Number.isFinite(Number(p.send_by_day))&&p.send_by_day!==null?Number(p.send_by_day):7);
 const draft=u[0];due.push({text:p.name+', '+d.label+': '+(today>sendBy?'overdue since '+day(sendBy):'send by '+day(sendBy))+(draft?' ('+String(draft.status).replace('_',' ')+')':' (no draft yet)'),overdue:today>sendBy});}
if(due.length)sec.push('Email updates due ('+due.length+(due.some(d=>d.overdue)?', '+due.filter(d=>d.overdue).length+' overdue':'')+'):\n'+due.slice(0,5).map(d=>'· '+d.text).join('\n')+more(due,5));
const meets=R['investorupdates.meetings'].rows.filter(m=>live(m)&&m.status!=='cancelled');
const soon=meets.filter(m=>m.meeting_date>=today&&m.meeting_date<=addDays(today,21)).sort((a,b)=>String(a.meeting_date).localeCompare(String(b.meeting_date)));
if(soon.length)sec.push('Meetings in the next 21 days ('+soon.length+'):\n'+soon.slice(0,5).map(m=>{const b=ups.find(u=>u.meeting_id===m.id&&u.format==='meeting_before'&&u.status!=='cancelled');const dueOn=addDays(m.meeting_date,-lead);return '· '+day(m.meeting_date)+' '+m.title+': agenda '+(b?String(b.status).replace('_',' '):today>dueOn?'late (due '+day(dueOn)+')':'due '+day(dueOn));}).join('\n')+more(soon,5));
const noRecap=meets.filter(m=>m.meeting_date<today&&m.meeting_date>=addDays(today,-60)&&!ups.some(u=>u.meeting_id===m.id&&u.format==='meeting_after'&&u.status==='sent'));
if(noRecap.length)sec.push('Meetings held without a recap ('+noRecap.length+'):\n'+noRecap.slice(0,5).map(m=>'· '+day(m.meeting_date)+' '+m.title).join('\n')+more(noRecap,5));
const waiting=ups.filter(u=>['in_review','approved'].includes(u.status));
if(waiting.length)sec.push('Drafts waiting ('+waiting.length+'):\n'+waiting.slice(0,5).map(u=>'· '+u.title+' ('+(u.status==='approved'?'approved, ready to send':'in review')+')').join('\n')+more(waiting,5));
const rs=R['investorupdates.responses'].rows,isQ=r=>r.ask_key==='question'||r.kind==='question';
const qs=rs.filter(r=>isQ(r)&&!r.answered_on&&r.status!=='done');
if(qs.length)sec.push('Unanswered questions ('+qs.length+'):\n'+qs.slice(0,5).map(r=>'· '+String(r.message||'(no text)').slice(0,120)).join('\n')+more(qs,5));
const help=rs.filter(r=>!isQ(r)&&(!r.status||['new','following_up'].includes(r.status)));
if(help.length)sec.push('Open offers of help ('+help.length+'):\n'+help.slice(0,5).map(r=>'· '+String(r.ask_text||r.ask_key||'Ask').slice(0,80)+(r.message?': '+String(r.message).slice(0,80):'')+(r.owner?' ('+r.owner+')':'')).join('\n')+more(help,5));
const complete=Object.values(R).every(x=>x.complete);
if(!sec.length)return {nonEmpty:false,text:'',subject:'Investor Updates'};
const text='Investor Updates · week of '+day(today)+'\n\n'+sec.join('\n\n')+(complete?'':'\n\nSome records could not be read; this digest may be incomplete.')+'\n\nOpen Investor Updates →';
return {nonEmpty:true,subject:'Investor Updates · week of '+day(today),text:text.slice(0,19000)};

