.iu-drawer-body{padding:16px 20px 28px;overflow-y:auto;display:flex;flex-direction:column;gap:14px}.iu-drawer-body>*{flex-shrink:0}
.iu-kvs{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:8px 16px}.iu-kv{display:flex;flex-direction:column;font-size:13px;min-width:0}.iu-kv span{color:var(--muted)}.iu-kv strong{font-size:14px;overflow-wrap:anywhere}
.iu-sub{border-top:1px solid var(--line);padding-top:12px;display:flex;flex-direction:column;gap:8px}.iu-sub h3,.iu-sub h4{margin:0;font-size:15px}
