.iu-facts{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:6px}.iu-facts li{display:flex;flex-wrap:wrap;gap:4px 10px;align-items:center;padding:8px 10px;border:1px solid #E3EAE6;border-radius:9px;font-size:14px}.iu-fact-src,.iu-fact-why{color:var(--muted);font-size:13px}.iu-fact-why{flex-basis:100%}
.iu-list{margin:0;padding-left:20px;display:flex;flex-direction:column;gap:6px;font-size:14px}
.iu-blocks{display:flex;flex-direction:column;gap:8px}.iu-blockrow{display:grid;grid-template-columns:minmax(0,1fr) 170px auto;gap:10px;align-items:end;padding:8px 0;border-bottom:1px solid #E8EEEB}.iu-blockrow>span{font-size:14px;overflow-wrap:anywhere;align-self:center}
.iu-editor{border:1px solid #BFDCCF;background:#F4FAF7;border-radius:10px;padding:12px}.iu-editor h4{margin:0 0 8px}
.iu-inline{display:flex;flex-wrap:wrap;gap:8px;margin-top:6px}.iu-inline .iu-input{flex:1 1 220px}
.iu-steps{margin:0;padding-left:22px;display:flex;flex-direction:column;gap:10px;font-size:14px}.iu-steps li.done{color:var(--green)}.iu-steps li.now{font-weight:600}
